private static void WriteArtifacts(PicoGK.Voxels body, string output, PicoGK.Library lib)
{
body.CalculateProperties(out float volume, out PicoGK.BBox3 measured);
if (!float.IsFinite(volume) || volume <= 0) throw new InvalidDataException("Empty body.");
body.SaveToVdbFile(Path.Combine(output, "part.vdb"));
using PicoGK.Mesh raw = new PicoGK.Mesh(body);
using PicoGK.Mesh clean = new PicoGK.Mesh(lib);
